.setcpu "6502"
.export se_native_font8
.segment "NATIVE_FONT"
; Deterministic chargen second-bank first128 glyphs, generated by tools/fonts.py.
; Runtime callers supply inverse through screen-code bit7, never a second bank.
se_native_font8:
    .incbin "assets/fonts/generated/native8.bin"
.assert *-se_native_font8=1024,error,"native UI font must contain128x8 bytes"
